// SPDX-License-Identifier: MPL-2.0
// K1 MUSE Book: host-side PowerVR register and firmware ABI generation.

//! Generates `../src/rogue/` from upstream's headers.
//!
//! The generator converts selected register definitions and firmware layouts
//! from the pinned headers into deterministic Rust output. `--check` compares
//! regenerated bytes with the committed files after the same rustfmt pass.
//!
//! The parser covers the selected header subset, not arbitrary C. Required
//! definitions must resolve; unrelated unevaluable defines may be omitted.
//! See CONVENTIONS.md for coverage limits and input provenance requirements.
//!
//! Generated output is committed. Normal kernel builds do not run this tool
//! or require its parser dependencies.
//!
//! # Usage
//!
//! ```text
//! # Offline, against a local Linux tree at the UPSTREAM commit:
//! cargo run --manifest-path kernel/core/comps/k1-musebook/pvr/regen/Cargo.toml -- \
//!     --linux /path/to/linux
//!
//! # Offline, against a directory of already-fetched headers:
//! cargo run --manifest-path kernel/core/comps/k1-musebook/pvr/regen/Cargo.toml -- \
//!     --headers /path/to/headers
//!
//! # Fetch headers into .cache/headers (needs network), then generate:
//! cargo run --manifest-path kernel/core/comps/k1-musebook/pvr/regen/Cargo.toml -- --fetch
//!
//! # CI: re-generate in memory and diff against committed files:
//! cargo run --manifest-path kernel/core/comps/k1-musebook/pvr/regen/Cargo.toml -- \
//!     --headers .cache/headers --check
//! ```
//!
//! Run from the repository root so its pinned rustfmt canonicalizes the output.
//!
//! The Linux tree / fetched headers must be at the commit recorded in
//! `../UPSTREAM`.

use std::{env, path::PathBuf, process::ExitCode};

use pvr_regen::{apply, ensure_headers, generate, read_upstream_commit, resolve_header_dir};

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("pvr-regen: {e}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> Result<(), String> {
    let mut linux: Option<PathBuf> = None;
    let mut headers: Option<PathBuf> = None;
    let mut check = false;
    let mut fetch = false;
    let mut out: Option<PathBuf> = None;

    let mut args = env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--linux" => {
                linux = Some(PathBuf::from(args.next().ok_or("--linux needs a path")?));
            }
            "--headers" => {
                headers = Some(PathBuf::from(args.next().ok_or("--headers needs a path")?));
            }
            "--out" => {
                out = Some(PathBuf::from(args.next().ok_or("--out needs a path")?));
            }
            "--check" => check = true,
            "--fetch" => fetch = true,
            "-h" | "--help" => {
                println!(
                    "Usage: pvr-regen [--linux DIR | --headers DIR] [--fetch] [--check] [--out DIR]"
                );
                return Ok(());
            }
            other => return Err(format!("unknown argument `{other}`")),
        }
    }

    if linux.is_some() && headers.is_some() {
        return Err("--linux and --headers are mutually exclusive".into());
    }

    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let upstream = manifest_dir.join("../UPSTREAM");
    let commit = read_upstream_commit(&upstream)?;

    let header_dir = if linux.is_none() && headers.is_none() {
        let cache = manifest_dir.join(".cache/headers");
        ensure_headers(&cache, &commit, fetch)?;
        cache
    } else {
        let dir = resolve_header_dir(linux.as_deref(), headers.as_deref())?;
        if fetch {
            ensure_headers(&dir, &commit, true)?;
        }
        for name in pvr_regen::REQUIRED_HEADERS {
            if !dir.join(name).exists() {
                return Err(format!("missing {} in {}", name, dir.display()));
            }
        }
        dir
    };

    let generated = generate(&header_dir, &commit).map_err(|e| e.to_string())?;
    let rogue_dir = out.unwrap_or_else(|| manifest_dir.join("../src/rogue"));
    apply(&generated, &rogue_dir, check)?;

    if check {
        eprintln!("pvr-regen: ok — committed rogue/ matches headers at {commit}");
    } else {
        eprintln!(
            "pvr-regen: wrote {} files under {}",
            generated.files().len(),
            rogue_dir.display()
        );
    }
    Ok(())
}
